<?php
require_user(true);
$tab=(string)($_GET['tab'] ?? 'overview');
$allowed=['overview','members','donations','enquiries','content','documents','settings','audit'];
if(!in_array($tab,$allowed,true)) $tab='overview';
?>
<div class="account-nav"><?php foreach($allowed as $t): ?><a class="<?= $tab===$t?'btn small':'text-link' ?>" href="/admin?tab=<?= e($t) ?>"><?= e(ucfirst($t)) ?></a><?php endforeach ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="logout"><button class="btn small">Sign out</button></form></div>
<?php if($tab==='overview'):
$metrics=[
 'Total donations'=>money((int)query("SELECT COALESCE(SUM(amount),0) FROM donations WHERE status='paid'")->fetchColumn()),
 'This month'=>money((int)query("SELECT COALESCE(SUM(amount),0) FROM donations WHERE status='paid' AND strftime('%Y-%m',paid_at)=strftime('%Y-%m','now')")->fetchColumn()),
 'Total donors'=>(string)query("SELECT COUNT(DISTINCT user_id) FROM donations WHERE status='paid'")->fetchColumn(),
 'Total members'=>(string)query('SELECT COUNT(*) FROM memberships')->fetchColumn(),
 'Pending memberships'=>(string)query("SELECT COUNT(*) FROM memberships WHERE status='pending'")->fetchColumn(),
 'Active members'=>(string)query("SELECT COUNT(*) FROM memberships WHERE status='approved' AND valid_until>=date('now')")->fetchColumn(),
 'Receipts issued'=>(string)query('SELECT COUNT(*) FROM donations WHERE receipt_no IS NOT NULL')->fetchColumn(),
 'Unpaid pledges'=>(string)query("SELECT COUNT(*) FROM donations WHERE status='pending'")->fetchColumn(),
]; ?>
<div class="grid"><?php foreach($metrics as $label=>$value): ?><div class="card card-body"><span class="eyebrow"><?= e($label) ?></span><h2><?= e($value) ?></h2></div><?php endforeach ?></div><div class="notice">Payments are disabled. Only verified paid donations contribute to donation totals. Pledges are tracked separately.</div>
<?php elseif($tab==='members'): $members=query('SELECT m.*,u.name,u.email FROM memberships m JOIN users u ON u.id=m.user_id ORDER BY m.id DESC')->fetchAll(); ?>
<div class="actions"><a class="btn small" href="/export?kind=members">Export Excel-compatible CSV</a><a class="text-link" href="/export?kind=members&format=pdf">Export PDF</a></div>
<?php if(!$members): ?><p>No membership applications yet.</p><?php endif ?>
<?php foreach($members as $m): ?><article class="card card-body admin-record"><div class="split"><div><span class="pill"><?= e(member_status($m)) ?></span><h3><?= e($m['name']) ?></h3><p><?= e($m['email']) ?><br><?= e($m['mobile']) ?><br><?= nl2br(e($m['address'])) ?></p><p><?= e($m['interest']) ?></p><p><?= nl2br(e($m['message'])) ?></p><strong><?= e($m['member_id']) ?></strong><?php if(member_status($m)==='approved'): ?><p><a class="text-link" href="/member-card?id=<?= $m['id'] ?>">ID card PDF</a> · <a class="text-link" href="/member-certificate?id=<?= $m['id'] ?>">Certificate PDF</a></p><?php endif ?></div><form method="post"><?= csrf() ?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?= $m['id'] ?>"><label>Decision<select name="status"><option value="approved">Approve / renew</option><option value="rejected">Reject / revoke</option></select></label><label>Valid until<input type="date" name="valid_until" value="<?= e($m['valid_until'] ?: date('Y-m-d',strtotime('+1 year'))) ?>"></label><label>Review note<textarea name="review_note" maxlength="1000"><?= e($m['review_note']) ?></textarea></label><button class="btn">Save decision</button></form></div></article><?php endforeach ?>
<?php elseif($tab==='donations'): $rows=query('SELECT * FROM donations ORDER BY id DESC')->fetchAll(); ?>
<div class="actions"><a class="btn small" href="/export?kind=donations">Export Excel-compatible CSV</a><a class="text-link" href="/export?kind=donations&format=pdf">Export PDF</a></div>
<div class="notice">No payment gateway is connected. Pending pledges cannot be marked as paid from this interface. Payment references and receipts will require a verified provider integration.</div>
<div class="table-scroll"><table><thead><tr><th>Donor / contact</th><th>Purpose</th><th>Amount</th><th>Status</th><th>Date / reference</th><th>Receipt</th></tr></thead><tbody><?php foreach($rows as $d): ?><tr><td><?= e($d['name']) ?><br><?= e($d['email']) ?><br><?= e($d['mobile']) ?></td><td><?= e($d['purpose']) ?></td><td><?= money($d['amount']) ?></td><td><?= e($d['status']==='pending'?'Unpaid pledge':$d['status']) ?></td><td><?= e($d['created_at']) ?><br><?= e($d['payment_id']) ?></td><td><?php if($d['receipt_no']): ?><a href="/receipt?id=<?= $d['id'] ?>"><?= e($d['receipt_no']) ?></a><?php else: ?>Not issued<?php endif ?></td></tr><?php endforeach ?></tbody></table></div>
<?php elseif($tab==='enquiries'): $rows=query('SELECT * FROM enquiries ORDER BY id DESC')->fetchAll(); ?>
<div class="actions"><a class="btn small" href="/export?kind=enquiries">Export Excel-compatible CSV</a><a class="text-link" href="/export?kind=enquiries&format=pdf">Export PDF</a></div>
<?php if(!$rows): ?><p>No enquiries yet.</p><?php endif ?><?php foreach($rows as $row): ?><article class="card card-body admin-record"><span class="pill"><?= e($row['category'].' · '.$row['status']) ?></span><h3><?= e($row['name']) ?></h3><p><?= e($row['email']) ?> · <?= e($row['mobile']) ?></p><p><?= e($row['organisation']) ?> <?= e($row['interest']) ?></p><p class="multiline"><?= e($row['message']) ?></p><form method="post"><?= csrf() ?><input type="hidden" name="action" value="enquiry-status"><input type="hidden" name="id" value="<?= $row['id'] ?>"><label class="check"><input type="checkbox" name="closed" <?= $row['status']==='closed'?'checked':'' ?>> Mark closed</label><button class="btn small">Save status</button></form></article><?php endforeach ?>
<?php elseif($tab==='content'): $edit=query('SELECT * FROM posts WHERE id=?',[(int)($_GET['edit'] ?? 0)])->fetch() ?: []; ?>
<form method="post"><?= csrf() ?><input type="hidden" name="action" value="post"><input type="hidden" name="id" value="<?= e($edit['id'] ?? '') ?>"><h3><?= $edit?'Edit content':'Publish an update' ?></h3><div class="fields"><label>Type<select name="type"><?php foreach(['event','news','story','initiative'] as $type): ?><option <?= ($edit['type'] ?? '')===$type?'selected':'' ?>><?= e($type) ?></option><?php endforeach ?></select></label><label>Date (optional)<input type="date" name="event_date" value="<?= e($edit['event_date'] ?? '') ?>"></label></div><label>Title<input name="title" maxlength="160" value="<?= e($edit['title'] ?? '') ?>" required></label><label>Content (plain text)<textarea name="body" maxlength="10000" required><?= e($edit['body'] ?? '') ?></textarea></label><label class="check"><input type="checkbox" name="published" <?= !empty($edit['published'])?'checked':'' ?>> Publish on website</label><button class="btn">Save content</button></form>
<?php foreach(query('SELECT * FROM posts ORDER BY id DESC')->fetchAll() as $post): ?><article class="card card-body admin-record"><span class="pill"><?= $post['published']?'Published':'Draft' ?> · <?= e($post['type']) ?></span><h3><?= e($post['title']) ?></h3><a class="text-link" href="/admin?tab=content&edit=<?= $post['id'] ?>">Edit</a><form method="post"><?= csrf() ?><input type="hidden" name="action" value="delete-post"><input type="hidden" name="id" value="<?= $post['id'] ?>"><button class="btn small">Delete content</button></form></article><?php endforeach ?>
<?php elseif($tab==='documents'): ?>
<form method="post" enctype="multipart/form-data"><?= csrf() ?><input type="hidden" name="action" value="upload"><h3>Upload a document or gallery image</h3><label>Title / image description<input name="title" maxlength="160" required></label><label>Category<select name="category"><option value="certificate">Registration / approval certificate</option><option value="gallery">Gallery photograph</option><option value="report">Annual / impact report</option></select></label><label>File (PDF, JPEG, PNG; maximum 5 MB)<input type="file" name="file" accept="application/pdf,image/jpeg,image/png" required></label><label class="check"><input type="checkbox" name="published"> Publish (I have verified this document and have permission to share it)</label><button class="btn">Upload</button></form>
<?php foreach(query('SELECT * FROM documents ORDER BY id DESC')->fetchAll() as $doc): ?><article class="card card-body admin-record"><h3><?= e($doc['title']) ?></h3><a class="text-link" href="/download?id=<?= $doc['id'] ?>">View file →</a><form method="post"><?= csrf() ?><input type="hidden" name="action" value="document-status"><input type="hidden" name="id" value="<?= $doc['id'] ?>"><label class="check"><input type="checkbox" name="published" <?= $doc['published']?'checked':'' ?>> Published</label><button class="btn small">Save visibility</button></form></article><?php endforeach ?>
<?php elseif($tab==='settings'): ?>
<form method="post"><?= csrf() ?><input type="hidden" name="action" value="settings"><h3>Foundation information</h3><?php foreach(['phone'=>'Phone / WhatsApp','email'=>'Contact email','address'=>'Office address','founder_message'=>'Founder / President message','leadership'=>'Governing body','mission'=>'Mission','vision'=>'Vision','registration_details'=>'Verified registration details'] as $key=>$label): ?><label><?= e($label) ?><textarea name="<?= e($key) ?>" maxlength="3000"><?= e(setting($key)) ?></textarea></label><?php endforeach ?><button class="btn">Save details</button></form>
<?php elseif($tab==='audit'): ?>
<div class="table-scroll"><table><thead><tr><th>Time (UTC)</th><th>User</th><th>Action</th><th>Detail</th></tr></thead><tbody><?php foreach(query('SELECT a.*,u.email FROM audit_log a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 500')->fetchAll() as $a): ?><tr><td><?= e($a['created_at']) ?></td><td><?= e($a['email']) ?></td><td><?= e($a['action']) ?></td><td><?= e($a['detail']) ?></td></tr><?php endforeach ?></tbody></table></div>
<?php endif ?>
